package com.swiftpay.analytics.entity; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant;
@Entity @Table(name="payment_analytics",uniqueConstraints=@UniqueConstraint(name="uk_analytics_transaction",columnNames="transaction_id")) public class PaymentAnalytics { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(name="transaction_id",nullable=false) String transactionId; @Column(nullable=false,precision=19,scale=4) BigDecimal amount; @Column(nullable=false) Instant completedAt; protected PaymentAnalytics(){} public PaymentAnalytics(String id,BigDecimal a){transactionId=id;amount=a;completedAt=Instant.now();} public BigDecimal getAmount(){return amount;} }